// src/lib/land/inhalte.js – Schnittstelle für Länderinhalte (für die Inhalts-Teams)
//
// Grundsatz: Eine Seite, ein Design. Länder unterscheiden sich nur in Texten, Werten und
// Bausteinen – nie in Layout oder Komponenten.
//
// 1) Land der Seite holen
//    Server-Seite:      const land = await seitenLand(params);        // src/lib/land/seite.js
//    Server-Baustein:   const land = landDerAnfrage();                // nach seitenLand() der Seite
//    Client-Baustein:   const { land } = useLand();                   // src/components/Land/useLand.js
//    land ist "DE" | "AT" | "CH" oder null (= gemeinsame Seite ohne Länderwahl).
//
// 2) Texte und Werte je Land
//    const TEXTE = {
//      gemeinsam: { titel: "Solarparks in DACH", lead: "…" },   // Pflicht: Stand wie vor Welle 2
//      AT: { lead: "… nach EAG und Landesraumordnung …" },        // nur, was in AT anders ist
//      CH: { lead: "… nach RPG Art. 24ter …" },
//    };
//    const t = inhaltFuer(TEXTE, land);   // AT: { titel aus gemeinsam, lead aus AT }
//    Fehlt ein Land, gilt „gemeinsam“. DE ohne eigenen Eintrag = gemeinsam.
//
// 3) Zahlen nur, wo sie für das Land geprüft sind
//    const modus = zahlenModus(land, ["DE"]);   // Länder, deren Werte an der Quelle geprüft sind
//      "zeigen"    → Werte normal anzeigen (Land ist geprüft)
//      "gemeinsam" → Werte anzeigen und dezent „gilt für Deutschland“ dazu (<GiltFuer />)
//      "hinweis"   → KEINE Werte, stattdessen <LandHinweis land={land} /> („… werden geprüft – Ergebnis auf Anfrage“)
//    Fertiger Baustein: <LandWerte land={land} geprueft={["DE"]}>…Werte…</LandWerte>
//    (src/components/Land/LandHinweis.js)
//
// 4) Rechner bekommen das Land automatisch: RechnerSeite liest landDerAnfrage(), die Rechner
//    useLand(); Startwerte über landStart() (src/components/Land/useLand.js). Für AT/CH greift
//    die Länder-Sperre der Länder-Engine (src/lib/invest/laender/sperre.js, marktFuer()).
//
// 5) Freigabe für Suchmaschinen: Erst wenn eine Seite für ein Land echten, geprüften Inhalt
//    rendert, den Eintrag in LAENDERINHALT (src/lib/land/seiten.js) mit Vermerk ergänzen. Dann
//    bekommt die Länderfassung index, eigenes canonical, hreflang und einen Sitemap-Eintrag.
//    Vorher bleibt sie noindex – sie ist trotzdem erreichbar und sieht gleich aus.

import { LAENDER, landCode } from "./laender.js";

const istObjekt = (x) => x !== null && typeof x === "object" && !Array.isArray(x) && !(x && x.$$typeof);

/**
 * Inhalt für ein Land mit Rückfall auf „gemeinsam“.
 * Objekte werden flach zusammengeführt (Land überschreibt gemeinsam), alles andere ersetzt.
 * @template T
 * @param {{ gemeinsam: T, DE?: Partial<T>|T, AT?: Partial<T>|T, CH?: Partial<T>|T }} inhalte
 * @param {string|null} land
 * @returns {T}
 */
export function inhaltFuer(inhalte, land) {
  if (!inhalte || !Object.hasOwn(inhalte, "gemeinsam")) throw new Error("inhaltFuer: Eintrag „gemeinsam“ fehlt");
  const l = landCode(land);
  const basis = inhalte.gemeinsam;
  if (!l || !Object.hasOwn(inhalte, l) || inhalte[l] === undefined) return basis;
  const eigen = inhalte[l];
  return istObjekt(basis) && istObjekt(eigen) ? { ...basis, ...eigen } : eigen;
}

/**
 * Wie Zahlenwerte im Land angezeigt werden.
 * @param {string|null} land
 * @param {string[]} geprueft Länder, deren Werte an der Originalquelle geprüft sind (Standard: nur DE)
 * @returns {"zeigen"|"gemeinsam"|"hinweis"}
 */
export function zahlenModus(land, geprueft = ["DE"]) {
  const l = landCode(land);
  if (!l) return "gemeinsam";
  return geprueft.includes(l) ? "zeigen" : "hinweis";
}

/** Text des Länderhinweises („Rechenwerte für die Schweiz werden geprüft – Ergebnis auf Anfrage“). */
export function landHinweisText(land, thema = "Rechenwerte") {
  const l = landCode(land) || "DE";
  return `${thema} ${LAENDER[l].fuerLand} werden geprüft – Ergebnis auf Anfrage`;
}
// Bausteine für Länderinhalte (Ländermodell) – ohne Hooks, also in Server- und Client-
// Komponenten nutzbar. Das Land kommt vom Aufrufer (Server: seitenLand()/landDerAnfrage(),
// Client: useLand()). Regeln und Beispiele: src/lib/land/inhalte.js.
//
//   <LandHinweis land="CH" />                         Block statt ungeprüfter Werte
//   <LandHinweis land="AT" thema="Pachtwerte" zeile /> kompakt, z. B. in einer Werteliste
//   <GiltFuer />                                      dezent „gilt für Deutschland“
//   <LandWerte land={land} geprueft={["DE"]}>…</LandWerte>
//       DE: Werte · gemeinsame Seite: Werte + „gilt für Deutschland“ · AT/CH: LandHinweis

import { Clock } from "lucide-react";
import Link from "@/components/Land/Link";
import { cn } from "@/components/ui/cn";
import { LAENDER, landCode, landHinweisText, zahlenModus } from "@/lib/land";

/** Hinweis statt Werten, die für das Land noch nicht an der Quelle geprüft sind. */
export function LandHinweis({ land, thema = "Rechenwerte", zeile = false, text, className }) {
  const l = landCode(land);
  if (!l) return null;
  const satz = text || `${landHinweisText(l, thema)}.`;
  if (zeile) {
    return (
      <p className={cn("flex items-start gap-2 text-[13.5px] leading-relaxed text-ink-600", className)} data-land-hinweis={l}>
        <Clock aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-navy-500" />
        <span>
          {satz}{" "}
          <Link href="/kontakt" className="font-semibold text-ov-700 underline decoration-ov-300 underline-offset-2 hover:decoration-current">
            Persönlich anfragen
          </Link>
        </span>
      </p>
    );
  }
  return (
    <div role="status" className={cn("rounded-3xl bg-sand-50 p-6 ring-1 ring-ink-200/70 md:p-8", className)} data-land-hinweis={l}>
      <p className="flex items-center gap-2 text-[13px] font-semibold uppercase tracking-[0.08em] text-ink-500">
        <Clock aria-hidden="true" className="h-4 w-4 text-navy-500" /> {LAENDER[l].name}
      </p>
      <p className="mt-3 max-w-prose text-[15px] leading-relaxed text-ink-700">{satz}</p>
      <Link
        href="/kontakt"
        className="mt-4 inline-flex min-h-[40px] items-center justify-center rounded-full bg-ov-600 px-4 text-[14px] font-semibold text-white transition-colors hover:bg-ov-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500 focus-visible:ring-offset-2"
      >
        Vorhaben persönlich besprechen
      </Link>
    </div>
  );
}

/** Dezenter Vermerk für deutsche Werte auf der gemeinsamen Seite (ohne Länderwahl). */
export function GiltFuer({ land = "DE", className, dunkel = false }) {
  const info = LAENDER[landCode(land) || "DE"];
  return <span className={cn("text-[12px] font-medium", dunkel ? "text-white/60" : "text-ink-500", className)}>(gilt {info.fuerLand})</span>;
}

/**
 * Werte nur zeigen, wo sie für das Land geprüft sind (siehe zahlenModus()).
 * @param {{ land: string|null, geprueft?: string[], thema?: string, zeile?: boolean, vermerk?: boolean, children: any }} p
 *   vermerk: auf der gemeinsamen Seite „gilt für Deutschland“ unter den Werten zeigen (Standard: ja)
 */
export function LandWerte({ land, geprueft = ["DE"], thema, zeile = false, vermerk = true, className, children }) {
  const modus = zahlenModus(land, geprueft);
  if (modus === "hinweis") return <LandHinweis land={land} thema={thema} zeile={zeile} className={className} />;
  if (modus === "gemeinsam" && vermerk && geprueft.length === 1) {
    return (
      <>
        {children}
        <p className="mt-2 text-right">
          <GiltFuer land={geprueft[0]} />
        </p>
      </>
    );
  }
  return children;
}
// src/lib/land/seiten.js – Register der öffentlichen Seiten und ihrer Länderinhalte
//
// SEITEN: jede öffentliche Seite mit ihrem Schlüssel (= Pfad ohne Länderpräfix, wie vor Welle 2).
//   Jede Seite existiert gemeinsam (/rechner/pacht) UND als Länderfassung (/de/rechner/pacht,
//   /at/…, /ch/…) mit DERSELBEN Seitenkomponente. Die Länderrouten unter
//   src/app/(laender)/[land]/… sind reine Weiterleitungen auf die gemeinsame Seite
//   (erzeugt mit scripts/landfassungen.mjs, geprüft in src/lib/land/routen.test.mjs).
//
// LAENDERINHALT: für welche Seite es in welchem Land ECHTEN eigenen Inhalt gibt (Recht, Zahlen,
//   Begriffe des Landes, fachlich geprüft). Nur diese Länderfassungen werden indexiert, bekommen
//   ein eigenes canonical, stehen im hreflang-Cluster und in der Sitemap. Alle anderen
//   Länderfassungen tragen noindex (die gemeinsame Seite bleibt die indexierte Fassung).
//   Eintragen erst nach Fachfreigabe; jeder Eintrag trägt einen Vermerk (Stand, Grundlage, Prüfer).
//   Die zweite Prüfperson ist noch nicht benannt (Entscheidung E6) → Prüfer „TODO-E6“.
//
